-- =========================================================
-- Lot 88 : devlog des mises à jour précédentes (lots 2 à 82).
-- À lancer après 0103. Peut être relancée sans risque : une entrée
-- déjà présente (même slug) n'est pas touchée.
--
-- Les lots 2 à 33 ont tous la date du 15 octobre 2026 (date d'arrivée de
-- leur historique) ; l'heure ne sert qu'à garder l'ordre.
-- Les lots 1, 29, 30, 40 et 52 n'ont pas d'entrée.
-- =========================================================

insert into public.devlog_entries (slug, title, body, tag, published_at) values
  ('lot-2', 'Messagerie et quêtes plus solides',
   'Les messages se modifient, se suppriment et se mettent en forme (gras, italique, couleur). Les messages privés affichent le pseudo de la personne. Une quête ne dépasse plus son nombre de places, même avec des clics simultanés. Arrivée de la **renommée** et de son classement, et de l''échéance des quêtes.', 'amelioration', '2026-10-15 06:20+02'),
  ('lot-3', 'La Cartographie reliée',
   'Les trajets se lancent depuis le Dossier Central : chemin le plus court, barre de progression et compte à rebours jusqu''à l''arrivée.', 'nouveau', '2026-10-15 06:30+02'),
  ('lot-4', 'Statistiques d''activité',
   'L''administration suit les visites, l''activité par jour et les achats. Le chat reçoit ses premières commandes d''effets (tremblement, confettis, pluie…).', 'admin', '2026-10-15 06:40+02'),
  ('lot-5', 'Notifications',
   'Un centre de notifications : messages reçus, quêtes validées, candidatures, arrivées à destination. Les notifications push du navigateur deviennent possibles. Nouvelles statistiques de la boutique : objet le plus vendu, meilleurs acheteurs et vendeurs.', 'nouveau', '2026-10-15 06:50+02'),
  ('lot-6', 'Notifications sur iPhone',
   'Le panneau des notifications se place correctement, et le site s''installe sur l''écran d''accueil de l''iPhone pour recevoir les notifications.', 'correctif', '2026-10-15 07:00+02'),
  ('lot-7', 'Renommée gagnée par les quêtes',
   'Une quête rapporte ou coûte de la renommée : un montant fixe, ou un calcul façon Elo selon la difficulté et ta renommée actuelle. Un responsable peut refuser un participant.', 'nouveau', '2026-10-15 07:10+02'),
  ('lot-8', 'Statistiques par objet',
   'Chaque objet de la boutique a ses chiffres : quantité vendue, revenu, acheteurs, évolution sur 8 semaines.', 'amelioration', '2026-10-15 07:20+02'),
  ('lot-9', 'Une page pour les notifications',
   'Les notifications ont leur propre page. Le calcul Elo de la renommée s''adapte à la renommée totale en jeu.', 'amelioration', '2026-10-15 07:30+02'),
  ('lot-10', 'Quêtes terminées masquées',
   'Le tableau des quêtes et « Mes missions en cours » n''affichent plus les quêtes terminées.', 'amelioration', '2026-10-15 07:40+02'),
  ('lot-11', 'Dette, épargne et salaires',
   'Emprunter fait passer le solde en négatif, avec des intérêts chaque jour et la boutique bloquée tant qu''on doit de l''argent. L''épargne en banque rapporte des intérêts composés. Les salaires sont versés même en ton absence.', 'economie', '2026-10-15 07:50+02'),
  ('lot-12', 'Entreprises, bourse, impôts et TVA',
   'Création d''entreprises cotées en bourse, avec trésorerie et prêts. Une TVA sur les ventes et un impôt hebdomadaire alimentent une caisse redistribuée chaque semaine.', 'economie', '2026-10-15 08:00+02'),
  ('lot-13', 'Gérer son entreprise de A à Z',
   'Employés et salaires, objets de boutique rattachés à l''entreprise, dividendes, registre des opérations, fermeture avec partage de la trésorerie, et « Mes emplois ».', 'economie', '2026-10-15 08:10+02'),
  ('lot-14', 'Classement de puissance, bourse plus réaliste',
   'Classement par puissance, cours de bourse plus réalistes, bannière d''annonces et nouveaux outils de modération.', 'amelioration', '2026-10-15 08:20+02'),
  ('lot-15', 'Fin de la téléportation, style personnalisé',
   'On choisit son point de départ une fois ; ensuite, changer de lieu demande un vrai trajet. Chaque membre peut habiller son profil, son badge de classement et sa carte d''organigramme avec son propre style.', 'nouveau', '2026-10-15 08:30+02'),
  ('lot-16', 'Style personnalisé réparé, création d''entreprise revue',
   'Le style personnalisé s''applique enfin, avec un exemple pré-rempli et un aperçu fidèle. Une entreprise se crée avec une mise de départ : le nombre d''actions est fixe et le prix en découle.', 'correctif', '2026-10-15 08:40+02'),
  ('lot-17', 'Éditeur visuel du style',
   'Plus besoin de code : couleurs, dégradés, lueur, arrondis et six animations en un clic, avec aperçu.', 'nouveau', '2026-10-15 08:50+02'),
  ('lot-18', 'Population simulée',
   'Cent habitants simulés vivent dans l''économie : salaires, achats, taxes, couples et naissances. De quoi faire tourner les prix et la bourse.', 'economie', '2026-10-15 09:00+02'),
  ('lot-19', 'Les entreprises qui vendent grandissent',
   'Une entreprise dont les ventes de la semaine dépassent une part de sa valeur reçoit de nouvelles actions à vendre.', 'economie', '2026-10-15 09:10+02'),
  ('lot-20', 'La monnaie devient le zéni',
   'Les crédits deviennent des zénis. Mot de passe oublié, bouton pour afficher le mot de passe, et confirmation d''e-mail par l''administration.', 'amelioration', '2026-10-15 09:20+02'),
  ('lot-21', 'Nouvel accueil',
   'L''accueil devient une grille d''icônes regroupées par thème, avec une barre du haut à la place du menu latéral. Le site garde l''endroit où tu étais. L''administration gagne un journal d''audit.', 'amelioration', '2026-10-15 09:30+02'),
  ('lot-22', 'Puissance calculée et entraînement',
   'La puissance devient la moyenne de trois facteurs : **Intelligence**, **Puissance** et **Technique**. Trois simulations d''entraînement apparaissent sur l''accueil : Donjons, Intelligence, Techniques.', 'nouveau', '2026-10-15 09:40+02'),
  ('lot-23', 'Les simulations comptent',
   'Les trois simulations sont branchées : une réussite fait progresser ton facteur. Le jeu reste ouvert après un résultat.', 'nouveau', '2026-10-15 09:50+02'),
  ('lot-24', 'Progression sur tous tes appareils',
   'Ta progression dans les simulations te suit d''un appareil à l''autre quand tu les ouvres depuis le Dossier Central.', 'amelioration', '2026-10-15 10:00+02'),
  ('lot-25', 'Compétences, niveaux et objets',
   'L''Intelligence est la moyenne de trois épreuves (Potions, Énigmes, Problème). Nouvel objet qui réinitialise les délais d''entraînement.', 'nouveau', '2026-10-15 10:10+02'),
  ('lot-26', 'Donjons plus durs',
   'Chaque île rend les monstres plus forts, et une réussite compte même si la partie avait commencé avant minuit.', 'amelioration', '2026-10-15 10:20+02'),
  ('lot-27', 'Raids de boss et dragon',
   'Battu par le gardien d''une île, tu peux appeler à l''aide : un autre membre te rejoint sur l''île. À partir de 90 de Puissance, le gardien est un dragon.', 'nouveau', '2026-10-15 10:30+02'),
  ('lot-28', 'Blessures et arbre technologique',
   'En Donjons, à partir du niveau 50, une défaite peut te blesser pour un temps. L''arbre technologique transforme tes réussites en bonus (primes de mission, impôts réduits…).', 'nouveau', '2026-10-15 10:40+02'),
  ('lot-31', 'Niveau 101 et rang Divin',
   'Après les 100 niveaux de Donjons, un dernier niveau attend, en solo et très difficile. Le réussir donne accès au rang **Divin**, au-dessus de S.', 'nouveau', '2026-10-15 11:10+02'),
  ('lot-32', 'Compte invisible',
   'Depuis Mon dossier, tu peux devenir invisible : tu disparais du trombinoscope, du classement et des listes. Ce que tu écris reste signé de ton nom.', 'nouveau', '2026-10-15 11:20+02'),
  ('lot-33', 'Bac à sable',
   'L''administration crée des comptes de test temporaires pour essayer le site comme un membre, sans gêner personne.', 'admin', '2026-10-15 11:30+02'),
  ('lot-34', 'Fiche membre, alertes, CGU',
   'Chaque membre a une fiche d''administration avec son journal complet. Des alertes signalent les activités inhabituelles. Arrivée des conditions d''utilisation, de la page de confidentialité et de « Mes données ».', 'admin', '2026-10-17 10:00+02'),
  ('lot-35', 'Titres et farces',
   'Des titres secrets se débloquent en jouant. Équipé, un titre s''affiche sur ton dossier et donne un pouvoir de farce à lancer sur les autres. Tu peux aussi indiquer ton anniversaire.', 'nouveau', '2026-10-17 12:00+02'),
  ('lot-36', 'Défi du Dragon',
   'Chaque farce a ses réglages. Le Défi du Dragon convoque des membres dans une arène en 3D où le lanceur incarne le dragon.', 'nouveau', '2026-10-17 14:00+02'),
  ('lot-37', 'Membres en ligne, Halloween',
   'L''accueil montre qui est sur le site en ce moment et ce qu''il fait ; tu peux te cacher depuis Mon dossier. Premier décor d''Halloween.', 'nouveau', '2026-10-17 16:00+02'),
  ('lot-38', 'Décors sur les trois sites',
   'Les décors de fête s''affichent aussi sur la Cartographie et le Wiki. La carte s''utilise mieux sur téléphone.', 'amelioration', '2026-10-17 18:00+02'),
  ('lot-39', 'Un seul système de trajet',
   'Les trajets lancés sur le Dossier Central ou la Cartographie sont les mêmes et se suivent en direct : plus d''arrivée immédiate ni de compte à rebours bloqué.', 'correctif', '2026-10-18 12:00+02'),
  ('lot-41', 'Noël',
   'Décor d''hiver : neige, aurore, sapins, chalet, guirlande et passage du traîneau. Un petit cadeau se cache en bas de page.', 'nouveau', '2026-10-21 12:00+02'),
  ('lot-42', 'Titres d''événement',
   'Halloween et Noël ont chacun un titre à gagner pendant l''événement.', 'nouveau', '2026-10-21 16:00+02'),
  ('lot-43', 'Correctifs',
   'Défi du Dragon qui ne s''ouvrait pas pour le lanceur, page 404 mal affichée, retour à la position, et plusieurs farces corrigées.', 'correctif', '2026-10-23 10:00+02'),
  ('lot-44', 'Les fêtes de l''année',
   'Sept nouveaux événements : Saint-Valentin, poisson d''avril, Pâques, 1er mai, fête de la musique, 14 juillet et 11 novembre, chacun avec son décor et son titre. Nouvelle traînée derrière le curseur.', 'nouveau', '2026-10-23 14:00+02'),
  ('lot-45', 'Pages plus rapides',
   'Les pages chargent leurs données en même temps au lieu d''attendre l''une après l''autre, et les décors ne se téléchargent qu''en saison.', 'amelioration', '2026-10-23 18:00+02'),
  ('lot-46', 'La Grande Chasse',
   'Du 9 au 15 mars : décor de volcan, passage de Brasombre, tableau de chasse sur l''accueil et un titre à gagner.', 'nouveau', '2026-10-24 10:00+02'),
  ('lot-47', 'Le ciel de Varyexis',
   'Pendant la Grande Chasse, lève les yeux la nuit : un secret se cache dans le ciel.', 'nouveau', '2026-10-24 14:00+02'),
  ('lot-48', 'De vrais paysages pour chaque fête',
   'Chaque fête a son paysage dessiné : manoir hanté, village enneigé, fonds marins, ville en fête…', 'amelioration', '2026-10-24 18:00+02'),
  ('lot-49', 'Icônes dessinées',
   'Les émojis laissent la place à des icônes dessinées pour le site, dans les menus, les notifications et les farces.', 'amelioration', '2026-10-25 10:00+02'),
  ('lot-50', 'Nouveau Wiki et nouvelle Cartographie',
   'Le Wiki devient le **Codex**, un cabinet de collection avec une couleur par catégorie. La Cartographie devient l''**Atlas**.', 'amelioration', '2026-10-25 14:00+02'),
  ('lot-51', 'Actions émises selon la demande',
   'Quand le stock d''actions d''une entreprise baisse, de nouvelles actions sont émises. L''augmentation de capital liée aux ventes devient plus généreuse.', 'economie', '2026-10-25 18:00+02'),
  ('lot-53', 'Tuto du Dossier Central',
   'Les nouveaux agents reçoivent leur dossier d''intégration. Une visite guidée de 24 étapes, le bouton « ? » et le Guide du S.I.D. expliquent le site.', 'nouveau', '2026-10-26 12:00+01'),
  ('lot-54', 'Renommée réparée',
   'Les récompenses de quête sont versées une seule fois, jamais à zéro, et la notification indique le montant. Les quêtes expirent correctement.', 'correctif', '2026-10-27 08:00+01'),
  ('lot-55', 'Quêtes à prendre sur place',
   'Une quête liée à un lieu ne se prend que si ton personnage y est. Les quêtes sans lieu se prennent de partout.', 'amelioration', '2026-10-27 10:00+01'),
  ('lot-56', 'Nouveau Comptoir',
   'Images en entier, recherche et filtres, fiche d''objet, « Mes achats », gestion du stock et aperçu en direct d''un nouvel objet. Les astuces du tuto peuvent être coupées.', 'amelioration', '2026-10-27 12:00+01'),
  ('lot-57', 'Animation de connexion',
   'Une courte animation après la connexion sur les trois sites, et l''accueil s''ouvre directement si tu es déjà connecté.', 'amelioration', '2026-10-27 14:00+01'),
  ('lot-58', 'Accessibilité',
   'Étiquettes de formulaire, meilleurs contrastes, focus visible, lien « Aller au contenu » et fenêtres utilisables au clavier sur les trois sites.', 'amelioration', '2026-10-27 16:00+01'),
  ('lot-59', 'Recherche Ctrl+K et surprises',
   'Une palette de recherche (Ctrl+K) trouve les pages, les membres et les quêtes. Arrivée du rapport de visite, de la courbe de renommée, des quêtes sur la carte et d''une énigme du jour.', 'nouveau', '2026-10-27 18:00+01'),
  ('lot-60', 'Carte d''agent, portefeuille, raccourcis',
   'Ta carte d''agent dans Mon dossier, l''évolution de ton portefeuille à la banque, jusqu''à 8 raccourcis sur l''accueil. La Cartographie suit le jour et la nuit à l''heure de Paris.', 'nouveau', '2026-10-27 20:00+01'),
  ('lot-61', 'Contrôle technique',
   'Vérification complète de la sécurité des trois sites : accès de la base resserrés, en-têtes de sécurité, dépendances verrouillées.', 'correctif', '2026-10-28 12:00+01'),
  ('lot-62', 'Jeu de rôle',
   'Messagerie RP : actions, hors-RP, narration et dés tirés par le serveur. Les quêtes ont un ordre de mission, un rapport à rédiger et les Chroniques du S.I.D.', 'nouveau', '2026-10-30 12:00+01'),
  ('lot-63', 'Nouvelle messagerie, nouveau tableau des missions',
   'Avatars, séparateurs de jours, bulles groupées et saisie compacte. Le tableau des missions a ses compteurs, ses filtres et ses fiches.', 'amelioration', '2026-10-31 12:00+01'),
  ('lot-64', 'Notifications push fiables',
   'Une notification pour chaque message, y compris sur iPhone, avec un panneau de test et de diagnostic dans Mon dossier. Barre du haut revue sur téléphone.', 'correctif', '2026-11-04 10:00+01'),
  ('lot-65', 'Enchères et sondages',
   'Les objets se vendent aux enchères depuis la boutique. L''administration publie des sondages.', 'nouveau', '2026-11-04 16:00+01'),
  ('lot-66', 'Souhaits, cadeaux et mariages',
   'Liste de souhaits et cadeaux entre membres, mariages, rapport de la semaine sur l''accueil. Les petites rentrées d''argent sont regroupées dans les notifications.', 'nouveau', '2026-11-05 10:00+01'),
  ('lot-67', 'Faillites et retraits validés',
   'Une entreprise qui vend trop peu en une semaine fait faillite ; une jauge prévient le fondateur. Les retraits d''entreprise sont validés par l''administration.', 'economie', '2026-11-05 14:00+01'),
  ('lot-68', 'Missions à cocher',
   'Chaque mission d''une quête a sa case à cocher, et le rapport a une partie par mission. Le commanditaire voit l''avancement.', 'amelioration', '2026-11-05 18:00+01'),
  ('lot-69', 'Économie réelle',
   'Une banque centrale ajuste l''économie chaque jour. La bourse passe au carnet d''ordres. Les impôts arrivent sous forme d''avis à payer, et les entreprises ont des frais.', 'economie', '2026-11-07 10:00+01'),
  ('lot-70', 'Réforme monétaire',
   'L''administration peut réformer la monnaie, avec des exceptions et une vérification obligatoire par un second admin avant application.', 'economie', '2026-11-07 13:00+01'),
  ('lot-71', 'Notifications regroupées',
   'Les notifications d''un même sujet se regroupent sur deux heures, même si tu les as déjà lues.', 'amelioration', '2026-11-07 16:00+01'),
  ('lot-72', 'Statistiques d''engagement',
   'Fréquentation, rétention et temps passé sur le site pour l''administration.', 'admin', '2026-11-07 19:00+01'),
  ('lot-73', 'Graphiques de bourse',
   'Graphiques en ligne ou en bougies, de 1 jour à tout l''historique, avec volumes et réticule.', 'economie', '2026-11-09 10:00+01'),
  ('lot-74', 'Administration de l''économie en onglets',
   'L''économie se gère par onglets : à traiter, banque centrale, impôts, membres, entreprises.', 'admin', '2026-11-09 14:00+01'),
  ('lot-75', 'Objectif de ventes automatique',
   'Le seuil de ventes hebdomadaire des entreprises se calcule seul à partir des ventes réelles. Validation des réformes corrigée.', 'economie', '2026-11-09 18:00+01'),
  ('lot-76', 'Roue du jour',
   'Une roue à tourner chaque jour : plus ta série de visites est longue, meilleures sont les chances. Une absence prolongée coûte une pénalité. Affichage revu sur téléphone.', 'nouveau', '2026-11-10 12:00+01'),
  ('lot-78', 'Fermer la Cartographie ou le Wiki',
   'L''équipe peut fermer temporairement un des sites. Les adresses des simulations se règlent depuis l''administration.', 'admin', '2026-11-12 16:00+01'),
  ('lot-81', 'Lieu inconnu partout',
   'Un membre en lieu inconnu disparaît de la carte et apparaît brouillé sur les trois sites, pseudo et avatar compris.', 'nouveau', '2026-11-16 10:00+01'),
  ('lot-82', 'Avatar brouillé et élection',
   'L''avatar brouillé reste lisible. L''élu de l''élection est retrouvé même avec des majuscules ou des espaces dans son pseudo.', 'correctif', '2026-11-16 12:00+01')
on conflict (slug) do nothing;

-- Corrections des entrées de départ de 0103, seulement si elles n'ont pas
-- été modifiées depuis la page (texte d'origine).
update public.devlog_entries
   set body = 'La part de la caisse commune réservée à l''administration va désormais aux seuls fondateurs.',
       title = 'Part admin de la caisse commune aux fondateurs',
       published_at = '2026-11-15 12:00+01'
 where slug = 'lot-79'
   and body = 'Les impôts hebdomadaires ne concernent plus que les fondateurs.';
update public.devlog_entries set published_at = '2026-11-16 08:00+01'
 where slug = 'lot-80' and published_at = '2026-11-14 12:00+01';
update public.devlog_entries set published_at = '2026-11-16 14:00+01'
 where slug = 'lot-83' and published_at = '2026-11-15 12:00+01';
update public.devlog_entries set published_at = '2026-11-17 12:00+01'
 where slug = 'lot-84' and published_at = '2026-11-16 12:00+01';
